import{_ as t,c as e,o,a2 as d}from"./chunks/framework.DdOM6S6U.js";const m=JSON.parse('{"title":"Table Internals","description":"","frontmatter":{"sidebarPos":43,"sidebarTitle":"Table Internals"},"headers":[],"relativePath":"guide/components/shared/table-internals.md","filePath":"guide/components/shared/table-internals.md","lastUpdated":1782593208000}'),a={name:"guide/components/shared/table-internals.md"},r=d('<h1 id="table-internals" tabindex="-1">Table Internals <a class="header-anchor" href="#table-internals" aria-label="Permalink to &quot;Table Internals&quot;">​</a></h1><p>These components are internal building blocks of <code>ue-data-table</code>. You do not use them directly — they are rendered automatically by the table.</p><h2 id="tableformattercell" tabindex="-1"><code>TableFormatterCell</code> <a class="header-anchor" href="#tableformattercell" aria-label="Permalink to &quot;`TableFormatterCell`&quot;">​</a></h2><p>Renders a single cell in the data table, applying the correct formatter strategy based on <code>col.formatter</code>.</p><h3 id="formatter-strategies" tabindex="-1">Formatter strategies <a class="header-anchor" href="#formatter-strategies" aria-label="Permalink to &quot;Formatter strategies&quot;">​</a></h3><table><thead><tr><th>Formatter value</th><th>Render</th></tr></thead><tbody><tr><td><code>&#39;edit&#39;</code> / <code>&#39;activate&#39;</code></td><td>Clickable primary-colour text. Clicking calls <code>itemAction</code></td></tr><tr><td><code>&#39;switch&#39;</code></td><td><code>v-switch</code> that calls <code>itemAction</code> on change</td></tr><tr><td><code>&#39;dynamic&#39;</code></td><td>Delegates to <code>ue-dynamic-component-renderer</code></td></tr><tr><td>Any other / array</td><td>Delegates to <code>ue-recursive-stuff</code> via <code>handleFormatter()</code></td></tr></tbody></table><h3 id="key-props" tabindex="-1">Key Props <a class="header-anchor" href="#key-props" aria-label="Permalink to &quot;Key Props&quot;">​</a></h3><table><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>col</code></td><td><code>Object</code></td><td>Column header definition (key, formatter, formatterName, isFormatting, hasCopy, target)</td></tr><tr><td><code>item</code></td><td><code>Object</code></td><td>The data record for the row</td></tr><tr><td><code>cellValue</code></td><td>any</td><td>Explicit cell value — overrides <code>item[col.key]</code> when set</td></tr><tr><td><code>cellOptions</code></td><td><code>Object</code></td><td>Extra cell config — currently supports <code>maxChars</code> for pre-shorten</td></tr><tr><td><code>handleFormatter</code></td><td><code>Function</code></td><td>Formatter resolution function provided by the table</td></tr><tr><td><code>itemAction</code></td><td><code>Function</code></td><td>Row action handler provided by the table</td></tr><tr><td><code>clickableRow</code></td><td><code>Boolean</code></td><td>True when the row itself is clickable (affects edit/activate cells)</td></tr><tr><td><code>groupContext</code></td><td><code>Boolean</code></td><td>True when the cell is inside a <code>group-by</code> header row</td></tr><tr><td><code>disableTooltip</code></td><td><code>Boolean</code></td><td>Skip <code>v-tooltip</code> — used in mobile/touch layouts</td></tr></tbody></table><hr><h2 id="tablegroupheaderrow" tabindex="-1"><code>TableGroupHeaderRow</code> <a class="header-anchor" href="#tablegroupheaderrow" aria-label="Permalink to &quot;`TableGroupHeaderRow`&quot;">​</a></h2><p>Renders the sticky group header row when <code>group-by</code> is active in <code>ue-data-table</code>. It shows the group value (with optional formatter), a row count badge, a collapse/expand toggle, and an optional select-all checkbox.</p><h3 id="key-props-1" tabindex="-1">Key Props <a class="header-anchor" href="#key-props-1" aria-label="Permalink to &quot;Key Props&quot;">​</a></h3><table><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>group</code></td><td><code>Object</code></td><td>Vuetify group object (<code>value</code>, <code>depth</code>, <code>items</code>)</td></tr><tr><td><code>columns</code></td><td><code>Array</code></td><td>Full column definitions — used for <code>colspan</code></td></tr><tr><td><code>formatterColumn</code></td><td><code>Object|null</code></td><td>Column definition whose formatter should render the group value</td></tr><tr><td><code>syntheticItem</code></td><td><code>Object</code></td><td>Synthetic row object used by <code>TableFormatterCell</code> in group context</td></tr><tr><td><code>handleFormatter</code></td><td><code>Function</code></td><td>Formatter resolution function from the table</td></tr><tr><td><code>itemAction</code></td><td><code>Function</code></td><td>Row action handler</td></tr><tr><td><code>showSelect</code></td><td><code>Boolean</code></td><td>Show the group-level select checkbox</td></tr><tr><td><code>disableFormatterTooltip</code></td><td><code>Boolean</code></td><td>Disable tooltips on the formatter cell (mobile mode)</td></tr></tbody></table><hr><h2 id="tableactions-table-tableactions-vue" tabindex="-1"><code>TableActions</code> (table/TableActions.vue) <a class="header-anchor" href="#tableactions-table-tableactions-vue" aria-label="Permalink to &quot;`TableActions` (table/TableActions.vue)&quot;">​</a></h2><p>A standalone row of action buttons rendered in the table toolbar or below the table. Accepts an <code>actions</code> array in the same format as <code>ue-form</code>&#39;s actions and renders each as a <code>v-btn</code> with optional badge, tooltip, and publish-switch variants.</p><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table><thead><tr><th>Prop</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>actions</code></td><td><code>Array</code></td><td>Action definitions (same shape as <code>ue-form</code> actions)</td></tr></tbody></table><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><table><thead><tr><th>Slot</th><th>Description</th></tr></thead><tbody><tr><td><code>prepend</code></td><td>Content placed before the action buttons</td></tr></tbody></table>',20),c=[r];function l(n,i,s,h,b,p){return o(),e("div",null,c)}const f=t(a,[["render",l]]);export{m as __pageData,f as default};
